namespace EnterpriseIam.Core.Cryptography
{
    #region Module 1: Cryptographic Engine (Password Hashing)

    public interface IPasswordHasher
    {
        byte[] GenerateSalt();
        string HashPassword(string password, byte[] salt);
        bool VerifyPassword(string password, string hashedPassword, byte[] salt);
    }

    /// <summary>
    /// Enterprise-grade PBKDF2-SHA512 password hashing implementation.
    /// Uses 310,000 iterations (OWASP recommendation) and constant-time comparisons.
    /// </summary>
    public class Pbkdf2PasswordHasher : IPasswordHasher
    {
        private const int Iterations = 310000; 
        private const int SaltSize = 32;       // 256 bits
        private const int HashSize = 64;       // 512 bits
        private static readonly HashAlgorithmName HashAlg = HashAlgorithmName.SHA512;

        public byte[] GenerateSalt()
        {
            return RandomNumberGenerator.GetBytes(SaltSize);
        }

        public string HashPassword(string password, byte[] salt)
        {
            if (string.IsNullOrWhiteSpace(password))
                throw new ArgumentException("Password cannot be null or empty.");

            using var pbkdf2 = new Rfc2898DeriveBytes(password, salt, Iterations, HashAlg);
            byte[] hash = pbkdf2.GetBytes(HashSize);
            return Convert.ToBase64String(hash);
        }

        public bool VerifyPassword(string password, string hashedPassword, byte[] salt)
        {
            if (string.IsNullOrWhiteSpace(password) || string.IsNullOrWhiteSpace(hashedPassword))
                return false;

            byte[] hashBytes = Convert.FromBase64String(hashedPassword);
            using var pbkdf2 = new Rfc2898DeriveBytes(password, salt, Iterations, HashAlg);
            byte[] computedHash = pbkdf2.GetBytes(HashSize);

            // Prevent timing attacks using a fixed-time comparison
            return CryptographicOperations.FixedTimeEquals(hashBytes, computedHash);
        }
    }

    #endregion
}

namespace EnterpriseIam.Core.Directory
{
    using Cryptography;

    #region Module 2: User Directory & Account Locking Service

    public class User
    {
        public Guid Id { get; set; } = Guid.NewGuid();
        public string Username { get; set; } = string.Empty;
        public string HashedPassword { get; set; } = string.Empty;
        public byte[] Salt { get; set; } = Array.Empty<byte>();
        public int FailedAccessAttempts { get; set; }
        public DateTimeOffset? LockoutEnd { get; set; }
        public List<string> Roles { get; set; } = new();
    }

    public record EnrollmentResult(bool Success, string ErrorMessage = "");
    public record AuthenticationResult(bool Authenticated, User? User, string ErrorMessage = "");

    public interface IUserDirectoryService
    {
        Task<EnrollmentResult> RegisterUserAsync(string username, string password, List<string> roles);
        Task<AuthenticationResult> AuthenticateUserAsync(string username, string password);
        Task<bool> UnlockUserAsync(string username);
    }

    /// <summary>
    /// Thread-safe directory managing registrations, authentications, and account locks.
    /// </summary>
    public class UserDirectoryService : IUserDirectoryService
    {
        private static readonly ConcurrentDictionary<string, User> UsersDb = new(StringComparer.OrdinalIgnoreCase);
        private readonly IPasswordHasher _passwordHasher;
        private readonly ILogger<UserDirectoryService> _logger;

        private const int MaxFailedAttempts = 5;
        private static readonly TimeSpan LockoutDuration = TimeSpan.FromMinutes(15);

        public UserDirectoryService(IPasswordHasher passwordHasher, ILogger<UserDirectoryService> logger)
        {
            _passwordHasher = passwordHasher;
            _logger = logger;
        }

        public Task<EnrollmentResult> RegisterUserAsync(string username, string password, List<string> roles)
        {
            if (string.IsNullOrWhiteSpace(username) || string.IsNullOrWhiteSpace(password))
                return Task.FromResult(new EnrollmentResult(false, "Username and password cannot be empty."));

            byte[] salt = _passwordHasher.GenerateSalt();
            string hash = _passwordHasher.HashPassword(password, salt);

            var newUser = new User
            {
                Username = username,
                HashedPassword = hash,
                Salt = salt,
                Roles = roles
            };

            if (UsersDb.TryAdd(username, newUser))
            {
                _logger.LogInformation("User account '{Username}' successfully registered.", username);
                return Task.FromResult(new EnrollmentResult(true));
            }

            return Task.FromResult(new EnrollmentResult(false, "User already exists."));
        }

        public Task<AuthenticationResult> AuthenticateUserAsync(string username, string password)
        {
            if (!UsersDb.TryGetValue(username, out var user))
            {
                _logger.LogWarning("Authentication failed: User '{Username}' not found.", username);
                return Task.FromResult(new AuthenticationResult(false, null, "Invalid credentials."));
            }

            // Check if account is locked out
            if (user.LockoutEnd.HasValue && user.LockoutEnd.Value > DateTimeOffset.UtcNow)
            {
                _logger.LogWarning("Authentication rejected: Account '{Username}' is locked.", username);
                var secondsRemaining = (int)(user.LockoutEnd.Value - DateTimeOffset.UtcNow).TotalSeconds;
                return Task.FromResult(new AuthenticationResult(false, null, $"Account locked. Try again in {secondsRemaining} seconds."));
            }

            // Verify Credentials
            bool isPasswordCorrect = _passwordHasher.VerifyPassword(password, user.HashedPassword, user.Salt);

            if (isPasswordCorrect)
            {
                // Reset failed attempts upon successful login
                user.FailedAccessAttempts = 0;
                user.LockoutEnd = null;
                _logger.LogInformation("User '{Username}' authenticated successfully.", username);
                return Task.FromResult(new AuthenticationResult(true, user));
            }

            // Increment failed access attempts
            user.FailedAccessAttempts++;
            if (user.FailedAccessAttempts >= MaxFailedAttempts)
            {
                user.LockoutEnd = DateTimeOffset.UtcNow.Add(LockoutDuration);
                _logger.LogWarning("Security Incident: Account '{Username}' locked due to too many failed attempts.", username);
                return Task.FromResult(new AuthenticationResult(false, null, $"Invalid credentials. Account locked for {LockoutDuration.TotalMinutes} minutes."));
            }

            _logger.LogWarning("Authentication failed for user '{Username}'. Failed attempts: {Attempts}", username, user.FailedAccessAttempts);
            return Task.FromResult(new AuthenticationResult(false, null, "Invalid credentials."));
        }

        public Task<bool> UnlockUserAsync(string username)
        {
            if (UsersDb.TryGetValue(username, out var user))
            {
                user.FailedAccessAttempts = 0;
                user.LockoutEnd = null;
                _logger.LogInformation("Account '{Username}' manually unlocked by administrator.", username);
                return Task.FromResult(true);
            }
            return Task.FromResult(false);
        }
    }

    #endregion
}

namespace EnterpriseIam.Core.Revocation
{
    #region Module 3: High-Performance Token Revocation Subsystem

    public interface ITokenRevocationService
    {
        void RevokeToken(string jti, DateTimeOffset expiry);
        bool IsTokenRevoked(string jti);
        void SweepExpiredTokens();
    }

    /// <summary>
    /// Thread-safe in-memory cache to manage blacklisted JWT tokens by JTI (JWT ID).
    /// </summary>
    public class InMemTokenRevocationService : ITokenRevocationService
    {
        private static readonly ConcurrentDictionary<string, DateTimeOffset> RevokedTokens = new();
        private readonly ILogger<InMemTokenRevocationService> _logger;

        public InMemTokenRevocationService(ILogger<InMemTokenRevocationService> logger)
        {
            _logger = logger;
        }

        public void RevokeToken(string jti, DateTimeOffset expiry)
        {
            if (string.IsNullOrWhiteSpace(jti)) return;

            // Only blacklist if token has remaining lifespan
            if (expiry > DateTimeOffset.UtcNow)
            {
                RevokedTokens[jti] = expiry;
                _logger.LogWarning("Token with JTI ID '{Jti}' has been explicitly revoked.", jti);
            }
        }

        public bool IsTokenRevoked(string jti)
        {
            if (string.IsNullOrWhiteSpace(jti)) return false;

            if (RevokedTokens.TryGetValue(jti, out var expiry))
            {
                if (expiry > DateTimeOffset.UtcNow)
                    return true;

                // Lazily evict expired key if hit during lookup
                RevokedTokens.TryRemove(jti, out _);
            }
            return false;
        }

        /// <summary>
        /// Cleans up expired tokens from the cache to prevent unbounded memory growth.
        /// </summary>
        public void SweepExpiredTokens()
        {
            var now = DateTimeOffset.UtcNow;
            int counter = 0;

            foreach (var kvp in RevokedTokens)
            {
                if (kvp.Value <= now)
                {
                    if (RevokedTokens.TryRemove(kvp.Key, out _))
                    {
                        counter++;
                    }
                }
            }

            if (counter > 0)
            {
                _logger.LogInformation("Pruning complete. Removed {Count} expired revoked tokens from memory store.", counter);
            }
        }
    }

    /// <summary>
    /// Background sweeping engine designed to clean expired blacklisted tokens periodically.
    /// </summary>
    public class RevocationCacheSweeper : BackgroundService
    {
        private readonly ITokenRevocationService _revocationService;
        private readonly ILogger<RevocationCacheSweeper> _logger;
        private static readonly TimeSpan Interval = TimeSpan.FromMinutes(1);

        public RevocationCacheSweeper(ITokenRevocationService revocationService, ILogger<RevocationCacheSweeper> logger)
        {
            _revocationService = revocationService;
            _logger = logger;
        }

        protected override async Task ExecuteAsync(CancellationToken stoppingToken)
        {
            _logger.LogInformation("Token Revocation background sweeping worker initialized.");

            while (!stoppingToken.IsCancellationRequested)
            {
                try
                {
                    _revocationService.SweepExpiredTokens();
                }
                catch (Exception ex)
                {
                    _logger.LogError(ex, "An error occurred while cleaning expired tokens.");
                }

                await Task.Delay(Interval, stoppingToken);
            }
        }
    }

    #endregion
}

namespace EnterpriseIam.Core.Oidc
{
    using Directory;

    #region Module 4: Asymmetric Cryptographic Keys & Token Generation Service

    public interface IKeyManager
    {
        RsaSecurityKey GetSigningKey();
        string GetKeyId();
        object GetJwks();
    }

    /// <summary>
    /// Ephemeral asymmetric keypair manager simulating Hardware Security Module (HSM) logic.
    /// Under production code, keys should be retrieved from Azure Key Vault, AWS KMS, or local store.
    /// </summary>
    public class AsymmetricKeyManager : IKeyManager
    {
        private readonly RSA _rsaKey;
        private readonly RsaSecurityKey _signingKey;
        private readonly string _keyId;

        public AsymmetricKeyManager()
        {
            _rsaKey = RSA.Create(2048);
            _keyId = Guid.NewGuid().ToString("N");
            _signingKey = new RsaSecurityKey(_rsaKey) { KeyId = _keyId };
        }

        public RsaSecurityKey GetSigningKey() => _signingKey;
        public string GetKeyId() => _keyId;

        /// <summary>
        /// Generates OpenID Connect standard JSON Web Key Set (JWKS) metadata payload.
        /// </summary>
        public object GetJwks()
        {
            var parameters = _rsaKey.ExportParameters(false);
            return new
            {
                keys = new[]
                {
                    new
                    {
                        kty = "RSA",
                        use = "sig",
                        kid = _keyId,
                        alg = "RS256",
                        n = Base64UrlEncoder.Encode(parameters.Modulus),
                        e = Base64UrlEncoder.Encode(parameters.Exponent)
                    }
                }
            };
        }
    }

    public interface IOidcTokenEngine
    {
        string GenerateAccessToken(User user, string issuer, string audience, int lifespanSeconds);
        string GenerateIdToken(User user, string issuer, string audience, string nonce, int lifespanSeconds);
    }

    /// <summary>
    /// OpenID Connect compliant JWT Generation Engine.
    /// </summary>
    public class OidcTokenEngine : IOidcTokenEngine
    {
        private readonly IKeyManager _keyManager;

        public OidcTokenEngine(IKeyManager keyManager)
        {
            _keyManager = keyManager;
        }

        public string GenerateAccessToken(User user, string issuer, string audience, int lifespanSeconds)
        {
            var key = _keyManager.GetSigningKey();
            var credentials = new SigningCredentials(key, SecurityAlgorithms.RsaSha256);
            var now = DateTime.UtcNow;

            var claims = new List<Claim>
            {
                new(JwtRegisteredClaimNames.Sub, user.Id.ToString()),
                new(JwtRegisteredClaimNames.UniqueName, user.Username),
                new(JwtRegisteredClaimNames.Jti, Guid.NewGuid().ToString()),
                new(JwtRegisteredClaimNames.Iat, new DateTimeOffset(now).ToUnixTimeSeconds().ToString(), ClaimValueTypes.Integer64)
            };

            foreach (var role in user.Roles)
            {
                claims.Add(new Claim(ClaimTypes.Role, role));
            }

            var token = new JwtSecurityToken(
                issuer: issuer,
                audience: audience,
                claims: claims,
                notBefore: now,
                expires: now.AddSeconds(lifespanSeconds),
                signingCredentials: credentials);

            return new JwtSecurityTokenHandler().WriteToken(token);
        }

        public string GenerateIdToken(User user, string issuer, string audience, string nonce, int lifespanSeconds)
        {
            var key = _keyManager.GetSigningKey();
            var credentials = new SigningCredentials(key, SecurityAlgorithms.RsaSha256);
            var now = DateTime.UtcNow;

            var claims = new List<Claim>
            {
                new(JwtRegisteredClaimNames.Sub, user.Id.ToString()),
                new(JwtRegisteredClaimNames.Iss, issuer),
                new(JwtRegisteredClaimNames.Aud, audience),
                new(JwtRegisteredClaimNames.Iat, new DateTimeOffset(now).ToUnixTimeSeconds().ToString(), ClaimValueTypes.Integer64),
                new(JwtRegisteredClaimNames.AuthTime, new DateTimeOffset(now).ToUnixTimeSeconds().ToString(), ClaimValueTypes.Integer64),
                new("preferred_username", user.Username)
            };

            if (!string.IsNullOrEmpty(nonce))
            {
                claims.Add(new Claim("nonce", nonce));
            }

            var token = new JwtSecurityToken(
                issuer: issuer,
                audience: audience,
                claims: claims,
                notBefore: now,
                expires: now.AddSeconds(lifespanSeconds),
                signingCredentials: credentials);

            return new JwtSecurityTokenHandler().WriteToken(token);
        }
    }

    #endregion
}

namespace EnterpriseIam.Web
{
    using Core.Cryptography;
    using Core.Directory;
    using Core.Oidc;
    using Core.Revocation;

    #region Web App Entry point & Controllers / Routing

    public class Program
    {
        public static void Main(string[] args)
        {
            var builder = WebApplication.CreateBuilder(args);

            // 1. Dependency Injection Configuration
            builder.Services.AddSingleton<IPasswordHasher, Pbkdf2PasswordHasher>();
            builder.Services.AddSingleton<IUserDirectoryService, UserDirectoryService>();
            builder.Services.AddSingleton<ITokenRevocationService, InMemTokenRevocationService>();
            builder.Services.AddSingleton<IKeyManager, AsymmetricKeyManager>();
            builder.Services.AddSingleton<IOidcTokenEngine, OidcTokenEngine>();

            // Hosted Background clean sweeper
            builder.Services.AddHostedService<RevocationCacheSweeper>();

            builder.Services.AddLogging(cfg => cfg.AddConsole());

            var app = builder.Build();

            // Seed Administrative and Demo accounts
            SeedUsers(app.Services.GetRequiredService<IUserDirectoryService>());

            // Helper issuer resolving delegate
            string GetIssuer(HttpContext ctx) => $"{ctx.Request.Scheme}://{ctx.Request.Host}";

            #region OIDC Discovery endpoints

            // Well-Known OpenID Configuration Endpoint
            app.MapGet("/.well-known/openid-configuration", (HttpContext context) =>
            {
                var issuer = GetIssuer(context);
                return Results.Ok(new
                {
                    issuer = issuer,
                    authorization_endpoint = $"{issuer}/connect/authorize",
                    token_endpoint = $"{issuer}/connect/token",
                    jwks_uri = $"{issuer}/.well-known/jwks.json",
                    revocation_endpoint = $"{issuer}/connect/revoke",
                    response_types_supported = new[] { "code", "token", "id_token" },
                    subject_types_supported = new[] { "public" },
                    id_token_signing_alg_values_supported = new[] { "RS256" },
                    scopes_supported = new[] { "openid", "profile", "email", "roles" },
                    token_endpoint_auth_methods_supported = new[] { "client_secret_post" }
                });
            });

            // JSON Web Key Set Endpoint (JWKS)
            app.MapGet("/.well-known/jwks.json", (IKeyManager keyManager) =>
            {
                return Results.Ok(keyManager.GetJwks());
            });

            #endregion

            #region Core OIDC & Identity Endpoints

            // Auth/Token generation exchange endpoint
            app.MapPost("/connect/token", async (HttpContext context, IUserDirectoryService dirService, IOidcTokenEngine tokenEngine) =>
            {
                var form = await context.Request.ReadFormAsync();
                var grantType = form["grant_type"].ToString();
                var username = form["username"].ToString();
                var password = form["password"].ToString();
                var nonce = form["nonce"].ToString();
                var audience = form["client_id"].ToString();

                if (string.IsNullOrWhiteSpace(audience))
                    audience = "enterprise-client";

                if (grantType != "password")
                {
                    return Results.BadRequest(new { error = "unsupported_grant_type", error_description = "Only 'password' flow is implemented for direct demo authentication." });
                }

                var authResult = await dirService.AuthenticateUserAsync(username, password);
                if (!authResult.Authenticated || authResult.User == null)
                {
                    return Results.Json(new { error = "invalid_grant", error_description = authResult.ErrorMessage }, statusCode: 400);
                }

                var issuer = GetIssuer(context);
                var accessToken = tokenEngine.GenerateAccessToken(authResult.User, issuer, audience, lifespanSeconds: 3600);
                var idToken = tokenEngine.GenerateIdToken(authResult.User, issuer, audience, nonce, lifespanSeconds: 3600);

                return Results.Ok(new
                {
                    access_token = accessToken,
                    token_type = "Bearer",
                    expires_in = 3600,
                    id_token = idToken,
                    scope = "openid profile roles"
                });
            });

            // Token Revocation Endpoint
            app.MapPost("/connect/revoke", async (HttpContext context, ITokenRevocationService revocationService) =>
            {
                var form = await context.Request.ReadFormAsync();
                var token = form["token"].ToString();

                if (string.IsNullOrWhiteSpace(token))
                {
                    return Results.BadRequest(new { error = "invalid_request", error_description = "Token parameter is missing." });
                }

                try
                {
                    var handler = new JwtSecurityTokenHandler();
                    if (handler.CanReadToken(token))
                    {
                        var jwt = handler.ReadJwtToken(token);
                        var jti = jwt.Id;
                        var exp = jwt.ValidTo;

                        if (!string.IsNullOrEmpty(jti))
                        {
                            revocationService.RevokeToken(jti, exp);
                            return Results.Ok();
                        }
                    }
                    return Results.BadRequest(new { error = "invalid_token", error_description = "Token does not possess a valid JWT configuration or JTI." });
                }
                catch (Exception)
                {
                    return Results.BadRequest(new { error = "invalid_token", error_description = "Malformed token payload." });
                }
            });

            #endregion

            #region Administrative & Verification Endpoints (Diagnostics)

            // Dynamic Account Registration Endpoint
            app.MapPost("/api/users/register", async (RegisterRequest req, IUserDirectoryService dirService) =>
            {
                var result = await dirService.RegisterUserAsync(req.Username, req.Password, req.Roles ?? new List<string> { "User" });
                if (result.Success)
                {
                    return Results.Ok(new { message = $"User '{req.Username}' registered successfully." });
                }
                return Results.BadRequest(new { error = result.ErrorMessage });
            });

            // Protected Resource Endpoint simulating access control validation inside the IAM Gateway
            app.MapGet("/api/secure-resource", async (HttpContext context, IKeyManager keyManager, ITokenRevocationService revocationService) =>
            {
                if (!context.Request.Headers.TryGetValue("Authorization", out var authHeader))
                {
                    return Results.Json(new { error = "unauthorized", details = "Missing authorization header." }, statusCode: 401);
                }

                var headerStr = authHeader.ToString();
                if (!headerStr.StartsWith("Bearer ", StringComparison.OrdinalIgnoreCase))
                {
                    return Results.Json(new { error = "unauthorized", details = "Malformed authentication protocol." }, statusCode: 401);
                }

                var token = headerStr.Substring("Bearer ".Length).Trim();
                var tokenHandler = new JwtSecurityTokenHandler();

                try
                {
                    // Basic syntax checking
                    var jwt = tokenHandler.ReadJwtToken(token);

                    // 1. Check if token is present on the dynamic blacklist
                    if (revocationService.IsTokenRevoked(jwt.Id))
                    {
                        return Results.Json(new { error = "invalid_token", details = "Token is explicitly revoked and blacklisted." }, statusCode: 401);
                    }

                    // 2. Validate cryptographically against active JWKS Key
                    var validationParams = new TokenValidationParameters
                    {
                        ValidateIssuerSigningKey = true,
                        IssuerSigningKey = keyManager.GetSigningKey(),
                        ValidateIssuer = true,
                        ValidIssuer = GetIssuer(context),
                        ValidateAudience = false, // Configured false for local resource gateway simulation
                        ClockSkew = TimeSpan.Zero
                    };

                    var principal = tokenHandler.ValidateToken(token, validationParams, out SecurityToken validatedToken);

                    return Results.Ok(new
                    {
                        message = "Access Granted to Secure Enterprise Resource",
                        subject = principal.FindFirst(ClaimTypes.NameIdentifier)?.Value,
                        user = principal.Identity?.Name,
                        roles = principal.FindAll(ClaimTypes.Role).Select(c => c.Value)
                    });
                }
                catch (SecurityTokenExpiredException)
                {
                    return Results.Json(new { error = "invalid_token", details = "Token has expired." }, statusCode: 401);
                }
                catch (Exception ex)
                {
                    return Results.Json(new { error = "invalid_token", details = $"Token validation error: {ex.Message}" }, statusCode: 401);
                }
            });

            #endregion

            app.Run();
        }

        private static void SeedUsers(IUserDirectoryService directoryService)
        {
            // Seed a standard admin user
            directoryService.RegisterUserAsync("admin@enterprise.com", "SecureP@ss123!", new List<string> { "Administrator", "IAM-Manager" }).Wait();
            // Seed a standard corporate employee user
            directoryService.RegisterUserAsync("employee@enterprise.com", "EmployeeP@ss55!", new List<string> { "Employee" }).Wait();
        }
    }

    public record RegisterRequest(string Username, string Password, List<string>? Roles);

    #endregion
}
